CREATE TABLE delivery_addresses(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id),label text NOT NULL,contact_name text NOT NULL,phone text NOT NULL,province text NOT NULL,city text NOT NULL,area text NOT NULL,street text NOT NULL,building text NOT NULL,landmark text NOT NULL DEFAULT '',version integer NOT NULL DEFAULT 1 CHECK(version>0),created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX user_delivery_addresses ON delivery_addresses(user_id,created_at);
ALTER TABLE checkout_orders ADD COLUMN shipping_address jsonb;
CREATE TABLE shipments(order_id uuid PRIMARY KEY,clinic_id uuid NOT NULL REFERENCES clinics(id),carrier text NOT NULL,tracking_code text NOT NULL,version integer NOT NULL DEFAULT 1,updated_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(order_id,clinic_id) REFERENCES clinic_orders(id,clinic_id));
CREATE TABLE shipment_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid NOT NULL,clinic_id uuid NOT NULL REFERENCES clinics(id),status text NOT NULL CHECK(status IN ('packed','shipped','delivered')),recorded_by uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(order_id,status),FOREIGN KEY(order_id,clinic_id) REFERENCES clinic_orders(id,clinic_id));
CREATE TRIGGER shipment_history_immutable BEFORE UPDATE OR DELETE ON shipment_events FOR EACH ROW EXECUTE FUNCTION protect_addendum();
